//   After move 6: 1
//   After move 7: 1
//   After move 8: 2
//   Pattern for start=2: 2, 1, 1, 0, 0, 1, 1, 2, ...
//   Cycle length is 6: [2, 1, 1, 0, 0, 1] for n=1 to 6.

// So we can compute the final position for each initial position (0, 1, 2) using the cycle,
// and find which initial position gives the final position x.

function getFinalPos(int $start, int $n): int {
    if ($n == 0) return $start;

    // Cycle length is 6
    $cycle = $n % 6;
    if ($cycle == 0) $cycle = 6;

    // Precomputed cycles for each start position
    // Index 0 corresponds to n=1, index 1 to n=2, etc.
    $cycles = [
        0 => [1, 2, 2, 1, 0, 0], // start at 0
        1 => [0, 0, 1, 2, 2, 1], // start at 1
        2 => [2, 1, 1, 0, 0, 1]  // start at 2
    ];

    return $cycles[$start][$cycle - 1];
}

