// Let's observe the pattern of permutations.

// Let's define the permutation for each move:
// Move 1 (odd): swap 0,1 -> [1, 0, 2]
// Move 2 (even): swap 1,2 -> [1, 2, 0]
// Move 3 (odd): swap 0,1 -> [2, 1, 0]
// Move 4 (even): swap 1,2 -> [2, 0, 1]
// Move 5 (odd): swap 0,1 -> [0, 2, 1]
// Move 6 (even): swap 1,2 -> [0, 1, 2]

// After 6 moves, we're back to identity. So the pattern repeats every 6 moves.

// We can compute the effective permutation after n moves by reducing n modulo 6.

function getPermutation($n) {
    $n = $n % 6;
    // Start with identity permutation: position i has ball at i
    // perm[i] = j means that if ball starts at i, after n moves it's at j
    // Actually, let's think differently.
    // Let's track where a ball starting at position p ends up after n moves.
    // Or better: let's track the inverse. We know the final position x, and we want the initial position.
    // So we need the inverse permutation.

    // Let's just simulate the first 6 moves to get the permutation mapping initial -> final.
    // Then we can invert it.

    // Simulate n moves on a ball starting at each position 0, 1, 2.
    $results = array();
    for ($start = 0; $start < 3; $start++) {
        $pos = $start;
        for ($i = 1; $i <= $n; $i++) {
            if ($i % 2 == 1) {
                // swap 0 and 1
                if ($pos == 0) $pos = 1;
                elseif ($pos == 1) $pos = 0;
            } else {
                // swap 1 and 2
                if ($pos == 1) $pos = 2;
                elseif ($pos == 2) $pos = 1;
            }
        }
        $results[$start] = $pos;
    }

    // Now $results[start] = final_pos
    // We want: given final_pos = x, find start.
    // So we invert the mapping.
    $inverse = array();
    for ($start = 0; $start < 3; $start++) {
        $inverse[$results[$start]] = $start;
    }

    return $inverse[$x];
}

